use inkism_engine::Engine;use serde_json::{json,Value};
fn ok(v:Value)->Value{assert_eq!(v["ok"],true,"{v}");v["data"].clone()}
#[test]
fn paged_reference_details_and_unlinked_titles_are_revision_guarded(){
 let dir=std::env::temp_dir().join(format!("inkism-connections-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&dir).unwrap();let path=dir.join("notes.db");
 {let e=Engine::open(path.to_str().unwrap()).unwrap();let target=ok(e.execute(json!({"op":"save","note":{"title":"Linked target","content":"<p id=\"block\">Body</p>","content_format":"html"}})));let mut titles=Vec::new();for i in 0..125{titles.push(ok(e.execute(json!({"op":"save","note":{"title":format!("Mention {i:03}"),"content":"","content_format":"markdown"}}))));}
 let links=(0..45).map(|i|format!("<p><a href=\"note://{}#^block\">Caption {i}</a></p>",target["id"].as_str().unwrap())).collect::<String>();let html=format!("<p>{}</p>{}<p>![[note://{}#^block|Embedded]]</p><p>Linked target {}</p>","padding ".repeat(300000),links,target["id"].as_str().unwrap(),titles.iter().map(|n|n["title"].as_str().unwrap()).collect::<Vec<_>>().join(" / "));
 let source=ok(e.execute(json!({"op":"save","note":{"title":"Large source","content":html,"content_format":"html"}})));ok(e.execute(json!({"op":"wait_index"})));
 let mut cursor=Value::Null;let mut refs=Vec::new();loop{let page=ok(e.execute(json!({"op":"outgoing_references","id":source["id"],"revision":source["revision"],"cursor":cursor})));assert!(page["items"].as_array().unwrap().len()<=20);refs.extend(page["items"].as_array().unwrap().clone());cursor=page["next_cursor"].clone();if cursor.is_null(){break;}}assert_eq!(refs.len(),46);assert!(refs[0]["reference"].as_str().unwrap().ends_with("#^block"));assert_eq!(refs[45]["embed"],true);assert_eq!(refs[45]["label"],"Embedded");
 let db=rusqlite::Connection::open(&path).unwrap();db.execute("UPDATE notes_meta SET locked=1 WHERE id=?1",[titles[0]["id"].as_str().unwrap()]).unwrap();let mut cursor=Value::Null;let mut mentions=std::collections::HashSet::new();loop{let page=ok(e.execute(json!({"op":"unlinked_mentions","id":source["id"],"revision":source["revision"],"cursor":cursor})));for item in page["items"].as_array().unwrap(){assert!(mentions.insert(item["id"].as_str().unwrap().to_string()));}cursor=page["next_cursor"].clone();if cursor.is_null(){break;}}assert_eq!(mentions.len(),124);assert!(!mentions.contains(target["id"].as_str().unwrap()));
 for op in ["outgoing_references","unlinked_mentions"]{assert_eq!(e.execute(json!({"op":op,"id":source["id"],"revision":9999}))["ok"],false);}
 db.execute("UPDATE notes_meta SET locked=1 WHERE id=?1",[source["id"].as_str().unwrap()]).unwrap();for op in ["outgoing_references","unlinked_mentions"]{assert_eq!(e.execute(json!({"op":op,"id":source["id"],"revision":source["revision"]}))["ok"],false);}
 }let _=std::fs::remove_dir_all(dir);
}
#[test]fn markdown_reference_details_preserve_embed_and_exclude_code(){let rows=inkism_engine::connection_index::references("```\n[[Fake]]\n```\n[Caption](note://abc#Heading)\n![[Other#^block|Embedded]]\n","markdown");assert_eq!(rows.len(),2);assert_eq!(rows[0]["reference"],"note://abc#Heading");assert_eq!(rows[0]["label"],"Caption");assert_eq!(rows[1]["reference"],"Other#^block");assert_eq!(rows[1]["embed"],true);assert_eq!(rows[1]["label"],"Embedded");}
#[test]fn large_markdown_previews_and_unicode_mentions_stay_bounded(){
 let dir=std::env::temp_dir().join(format!("inkism-reference-preview-{}",uuid::Uuid::new_v4()));std::fs::create_dir_all(&dir).unwrap();let path=dir.join("notes.db");{
 let e=Engine::open(path.to_str().unwrap()).unwrap();let mention=ok(e.execute(json!({"op":"save","note":{"title":"ÄPFEL","content":"","content_format":"markdown"}})));let source=format!("{}\n\n# Section\n\näpfel exact paragraph ^block\n\n# Next\n\nNot in section\n","padding ".repeat(300000));let note=ok(e.execute(json!({"op":"save","note":{"title":"Large MD preview","content":source,"content_format":"markdown"}})));ok(e.execute(json!({"op":"wait_index"})));
 for anchor in ["","Section","section","^block"]{let page=ok(e.execute(json!({"op":"reference_preview","id":note["id"],"revision":note["revision"],"anchor":anchor})));let item=&page["item"];assert!(!item.is_null(),"{anchor}: {page}");assert!(item["source"].as_str().unwrap().len()<=65536);if anchor.is_empty(){assert_eq!(item["truncated"],true);}else{assert!(item["byte_offset"].as_u64().unwrap()>2*1024*1024);assert!(!item["source"].as_str().unwrap().contains("Not in section"));}}
 let mentions=ok(e.execute(json!({"op":"unlinked_mentions","id":note["id"],"revision":note["revision"]})));assert_eq!(mentions["items"][0]["id"],mention["id"]);assert_eq!(e.execute(json!({"op":"reference_preview","id":note["id"],"revision":9999,"anchor":"Section"}))["ok"],false);
 let after=ok(e.execute(json!({"op":"get","id":note["id"]})));assert_eq!(after["content"],source);
 }let _=std::fs::remove_dir_all(dir);
}
